 const lights=[[210,180],[310,180],[410,180],[210,280],[310,280],[410,280],[580,180],[740,190],[740,290],[240,420],[340,420],[740,460]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="8"/><path d="M${x-11} ${y}h22M${x} ${y-11}v22"/>`).join('');
