 async function handlePlanFiles(files){const max=25*1024*1024;for(const file of files){try{if(file.size>max)throw new Error('Use plan files smaller than 25 MB in this prototype.');state.pdfBusy=true;notify('Reading plan locally. Large PDF sets are limited to 20 pages.');let pages=[];
  if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){if(!options.pdfRenderer)throw new Error('PDF rendering is not configured for this preview. Use a PNG/JPEG sheet or wire the approved CMI PDF renderer.');pages=await options.pdfRenderer(file);}
  else if(['image/png','image/jpeg'].includes(file.type)){const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read the image.'));reader.readAsDataURL(file);});const img=new Image();img.src=data;await img.decode();if(img.width*img.height>40000000)throw new Error('Image pixel dimensions exceed the prototype limit.');const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=Math.round(img.height*1000/img.width);if(canvas.height>6000)throw new Error('Image aspect ratio exceeds the prototype limit.');canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);pages=[{image:canvas.toDataURL('image/png'),width:canvas.width,height:canvas.height,page:1}];}
  else throw new Error('Supported plan inputs: PDF, PNG, or JPEG.');
  if(!Array.isArray(pages)||!pages.length||pages.length>20)throw new Error('The PDF adapter must return 1–20 rendered pages.');
  if(pages.some(p=>!/^data:image\/(png|jpeg);base64,/.test(p.image)||!Number.isFinite(p.width)||!Number.isFinite(p.height)||p.width<=0||p.height<=0||p.width*p.height>40000000))throw new Error('Invalid rendered page supplied by the PDF adapter.');
  if(destroyed)return;if(!Array.isArray(pages)||!pages.length||pages.length>20)throw new Error('The renderer must return between 1 and 20 pages.');for(const page of pages){if(!Number.isFinite(page.width)||!Number.isFinite(page.height)||page.width<=0||page.height<=0||page.width*page.height>10000000||typeof page.image!=='string'||!/^data:image\/(png|jpeg);base64,/i.test(page.image))throw new Error('The renderer returned an invalid or oversized raster page.');}checkpoint();pages.forEach((p,i)=>{const s={id:uid(),number:'U-'+String(job().sheets.length+1).padStart(3,'0'),name:file.name+(pages.length>1?' · page '+(i+1):''),revision:'NEW',width:p.width,height:p.height,image:p.image,scale:null,verified:false,demo:false,sourceFilename:file.name,sourcePage:p.page||i+1};job().sheets.push(s);state.sheetId=s.id;});state.tab='takeoff';state.zoom=1;state.pan={x:0,y:0};state.points=[];state.tool='select';log(`Added ${pages.length} plan page(s) from ${file.name}; scale unverified.`);render();notify('Plan added locally. Calibrate each sheet before measuring.');
  }catch(err){notify(err.message||'Plan loading failed. Try PNG/JPEG or configure a self-hosted PDF renderer.');}finally{state.pdfBusy=false;}}}
 function exportCSV(){const t=estimateTotals(job()),rows=[['Job','Cost code','Takeoff item','Origin','Net quantity','Unit','Material waste percent','Material quantity','Material unit cost','Labor unit cost','Equipment unit cost','Subcontract unit cost','Direct line total']];t.lines.forEach(l=>rows.push([job().number,l.item.code,l.item.name,l.item.origin,round(l.qty,6),l.item.unit,l.item.waste,round(l.materialQty,6),l.item.material,l.item.labor,l.item.equipment||0,l.item.sub||0,l.total]));rows.push(['SUMMARY','Direct cost',t.direct],['SUMMARY','Material tax scenario',t.tax],['SUMMARY','Contingency',t.contingency],['SUMMARY','Pricing method',job().pricingMode],['SUMMARY','Rate percent',job().rate],['SUMMARY','Gross profit',t.profit],['SUMMARY','Estimate total',t.price]);downloadFile('CMI-estimate.csv',encodeCSV(rows.map(r=>[...r,...Array(Math.max(0,rows[0].length-r.length)).fill('')])),'text/csv;charset=utf-8');notify('Estimate CSV exported from this local session.');}
 function exportJSON(){downloadFile('CMI-takeoff-session.json',JSON.stringify({format:'cmi-takeoff-prototype',schemaVersion:1,exportedAt:new Date().toISOString(),status:'LOCAL_PROTOTYPE_NOT_PRODUCTION',restoreSupported:false,jobs:state.jobs,reviewedSampleChanges:state.reviewed},null,2),'application/json');notify('Session JSON exported. This is a developer handoff, not a restore file.');}
 const actions={
  tab(el){state.tab=el.dataset.id;state.points=[];state.hover=null;render();},theme(){state.theme=state.theme==='light'?'dark':'light';options.onThemeChange?.(state.theme);q('.studio')?.setAttribute('data-theme',state.theme);render();},help(){openModal('help');},new(){openModal('new');},'close-modal'(){closeModal();},bolt(){openModal('bolt');},proposal(){openModal('proposal');},'migration-info'(){openModal('migration');},'revision-register'(){openModal('revision-register');},
  sheet(el){state.sheetId=el.dataset.id;state.points=[];state.selectedGeometry=null;state.zoom=1;state.pan={x:0,y:0};state.tool='select';render();},item(el){state.itemId=el.dataset.id;state.points=[];state.selectedGeometry=null;state.tool='select';render();},visibility(el){const id=el.dataset.id;state.hidden.has(id)?state.hidden.delete(id):state.hidden.add(id);render();},inspect(el){state.itemId=el.dataset.id;state.tab='takeoff';state.tool='select';render();},tool(el){selectTool(el.dataset.id);},'add-item'(){openModal('add-item');},'upload-plan'(){q('#planfile').click();},'choose-csv'(){q('#csvfile').click();},'sample-import'(){loadCSV(SAMPLE_CSV,'sample-constructconnect-quantities.csv');},'sample-download'(){downloadFile('sample-constructconnect-quantities.csv',SAMPLE_CSV,'text/csv');},source(el){state.source=el.dataset.id;render();},
  'create-job'(){const name=q('#new-name').value.trim(),number=q('#new-number').value.trim();if(!name||!number){notify('Enter a project name and a job reference.');return;}if(state.jobs.some(j=>j.number===number)){notify('Use a unique local job reference.');return;}const n=makeDemoJob();n.id=uid();n.name=name;n.number=number;n.type=q('#new-type').value;n.items=[];n.geometry=[];n.sheets=n.sheets.slice(0,1);n.imports=[];n.activity=[{text:'New local estimate created with a demonstration plan.',at:'This session'}];n.status='Draft';state.jobs.push(n);state.jobIndex=state.jobs.length-1;state.undo=[];state.redo=[];state.itemId=null;state.sheetId=n.sheets[0].id;state.modal=null;state.tab='takeoff';render();notify('Local estimate created. Add takeoff items or import quantities.');},
  'create-item'(){const name=q('#new-item-name').value.trim();if(!name){notify('Enter a takeoff item name.');return;}const kind=q('#new-item-kind').value;const it={id:uid(),name,code:q('#new-item-code').value.trim()||'UNMAPPED',unit:{area:'SF',linear:'LF',count:'EA',volume:'CY'}[kind],kind,color:['#688579','#bd925d','#7b90b9','#b77c70','#9682a3'][job().items.length%5],material:checkNumber(q('#new-item-material')),labor:checkNumber(q('#new-item-labor')),waste:checkNumber(q('#new-item-waste'),0,100),depth:checkNumber(q('#new-item-depth'),.001,100),baseQty:0,equipment:0,sub:0,taxable:true,origin:'measured',area:q('#new-item-area').value.trim()||'Unassigned'};checkpoint();job().items.push(it);state.itemId=it.id;state.modal=null;state.tool=sheet().verified||kind==='count'?kind:'calibrate';state.points=[];log('Created takeoff item '+name+'.');render();notify('Item created. Click the plan to start measuring.');},
  calibrate(){state.tool='calibrate';state.points=[];state.hover=null;render();notify('Click two points whose real-world distance you know.');},'cancel-scale'(){state.points=[];state.tool='select';state.modal=null;render();},'apply-scale'(){if(!q('#scale-ack').checked){notify('Confirm the scale verification before applying.');return;}const distance=checkNumber(q('#known-distance'),.001,100000),pixels=pathLength(state.points);if(pixels<1){notify('The calibration points are too close. Select a longer known dimension.');return;}checkpoint();const s=sheet();s.scaleHistory=[...(s.scaleHistory||[]),{previous:s.scale,scale:distance/pixels,at:new Date().toISOString(),points:structuredClone(state.points),knownFeet:distance}];s.scale=distance/pixels;s.verified=true;state.points=[];state.tool='select';state.modal=null;log('Verified scale for '+s.number+'.');render();notify('Sheet scale updated; measured quantities recalculated.');},finish:finishDrawing,
  undo(){if(!state.undo.length)return;state.redo.push(structuredClone(job()));state.jobs[state.jobIndex]=state.undo.pop();state.selectedGeometry=null;state.points=[];render();notify('Undid the last local job change.');},redo(){if(!state.redo.length)return;state.undo.push(structuredClone(job()));state.jobs[state.jobIndex]=state.redo.pop();state.selectedGeometry=null;render();notify('Redid the local job change.');},
  'delete-geometry'(){if(!state.selectedGeometry)return;checkpoint();job().geometry=job().geometry.filter(g=>g.id!==state.selectedGeometry);state.selectedGeometry=null;log('Deleted a measured object.');render();},deduct(){const g=job().geometry.find(g=>g.id===state.selectedGeometry);if(!g)return;checkpoint();g.deduct=!g.deduct;log(g.deduct?'Marked an object as a deduction.':'Removed an object deduction.');render();notify('Deduction updated. Net quantity is floored at zero in this prototype.');},
  'zoom-in'(){zoomBy(1.2);},'zoom-out'(){zoomBy(1/1.2);},fit(){state.zoom=1;state.pan={x:0,y:0};render();},
  'export-csv':exportCSV,'export-json':exportJSON,'export-svg'(){const s=sheet();downloadFile(s.number+'-takeoff.svg',`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${s.width} ${s.height}" width="${s.width}" height="${s.height}">${drawing(s)}${geometryMarkup()}<text x="55" y="30" font-family="Arial" font-size="9" fill="#986c39">LOCAL CMI PROTOTYPE · NOT FOR CONSTRUCTION</text></svg>`,'image/svg+xml');notify('Current visible plan layers exported as SVG.');},print(){state.tab='estimate';state.modal=null;render();requestAnimationFrame(()=>notify('Use Export CSV or Export SVG in this preview. Branded PDF output is a production adapter task.'));},
  'review-change'(el){state.reviewed.includes(el.dataset.id)?state.reviewed=state.reviewed.filter(id=>id!==el.dataset.id):state.reviewed.push(el.dataset.id);render();},vendor(el){checkpoint();job().selectedVendor=el.dataset.id;log('Selected demo vendor '+el.dataset.id.toUpperCase()+' for local review.');render();notify('Selection saved in this session only. No award or purchase order was sent.');},assembly(el){openModal('assembly',{id:el.dataset.id});},'apply-assembly'(){const a=ASSEMBLIES.find(a=>a.id===state.modal.id),target=job().items.find(i=>i.id===q('#assembly-target').value);if(!target||target.unit!==a.unit){notify('Choose a takeoff item with a matching unit.');return;}checkpoint();Object.assign(target,{material:a.material,labor:a.labor,waste:a.waste,assemblySnapshot:{id:a.id,version:'DEMO-1',appliedAt:new Date().toISOString()}});log('Applied sample '+a.name+' rates to '+target.name+'.');state.modal=null;render();notify('Sample assembly rates applied to the selected line.');},
  'import-back'(){state.importStep=Math.max(1,state.importStep-1);state.ack=false;render();},'restart-import'(){state.importStep=1;state.parsed=null;state.validation=null;state.ack=false;render();},'validate-import'(){if(['name','qty','unit'].some(k=>state.mapping[k]===''||state.mapping[k]===undefined)){notify('Map the required name, quantity, and unit columns.');return;}if(new Set(['name','qty','unit'].map(k=>state.mapping[k])).size!==3){notify('Name, quantity, and unit must use different columns.');return;}state.validation=mapCSV(state.parsed,state.mapping);state.importStep=3;state.ack=false;render();},
  'commit-import'(){const v=state.validation;if(!state.ack||!v||v.issues.length||!v.results.length){notify('Resolve validation errors and acknowledge the source review first.');return;}if(job().imports.some(i=>i.hash===state.importHash)){notify('Duplicate source file blocked for this local job.');return;}checkpoint();const batchId=uid();v.results.forEach((r,index)=>job().items.push({id:uid(),name:r.name,code:r.code,kind:{SF:'area',LF:'linear',EA:'count',CY:'volume'}[r.unit],unit:r.unit,color:['#688579','#bd925d','#7b90b9'][index%3],baseQty:r.qty,material:r.material,labor:r.labor,waste:0,equipment:0,sub:0,taxable:true,origin:'imported',geometryFidelity:'quantity_only',area:r.area,source:{batchId,filename:state.importName,row:r.row,hash:state.importHash}}));job().imports.push({id:batchId,sourceEdition:state.source,filename:state.importName,hash:state.importHash,sourceText:state.importText,headers:state.parsed.headers,rows:state.parsed.rows,mapping:structuredClone(state.mapping),recordCount:v.results.length,geometryFidelity:'quantity_only',at:new Date().toISOString(),reviewAcknowledged:true});state.importCount=v.results.length;state.importStep=4;log('Imported '+v.results.length+' quantity-only rows from '+state.importName+'.');render();}
 };
 function zoomBy(factor){const next=Math.max(.4,Math.min(4,state.zoom*factor)),ratio=next/state.zoom,s=sheet();state.pan={x:s.width/2-(s.width/2-state.pan.x)*ratio,y:s.height/2-(s.height/2-state.pan.y)*ratio};state.zoom=next;render();}
